REVOKE ALL ON public.app_user_activity, public.app_usage_logs FROM anon, authenticated;
CREATE SCHEMA IF NOT EXISTS private;
GRANT USAGE ON SCHEMA private TO authenticated;
ALTER FUNCTION public.record_app_usage(text,text) SET SCHEMA private;
ALTER FUNCTION public.admin_module_usage(timestamptz) SET SCHEMA private;
CREATE FUNCTION public.record_app_usage(p_module text DEFAULT NULL, p_event_kind text DEFAULT 'navigation') RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT private.record_app_usage(p_module,p_event_kind); $$;
CREATE FUNCTION public.admin_module_usage(p_since timestamptz) RETURNS TABLE(module text, accesses bigint, users_count bigint) LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM private.admin_module_usage(p_since); $$;
CREATE FUNCTION private.admin_activity_page(p_offset integer) RETURNS TABLE(user_id uuid,last_active_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Administrator required'; END IF; RETURN QUERY SELECT a.user_id,a.last_active_at FROM public.app_user_activity a ORDER BY a.user_id LIMIT 500 OFFSET greatest(p_offset,0); END $$;
CREATE FUNCTION public.admin_activity_page(p_offset integer DEFAULT 0) RETURNS TABLE(user_id uuid,last_active_at timestamptz) LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM private.admin_activity_page(p_offset); $$;
CREATE FUNCTION private.admin_usage_logs_page(p_offset integer) RETURNS TABLE(id uuid,user_id uuid,module text,event_kind text,created_at timestamptz) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT public.is_admin(auth.uid()) THEN RAISE EXCEPTION 'Administrator required'; END IF; RETURN QUERY SELECT l.id,l.user_id,l.module,l.event_kind,l.created_at FROM public.app_usage_logs l ORDER BY l.created_at DESC,l.id LIMIT 500 OFFSET greatest(p_offset,0); END $$;
CREATE FUNCTION public.admin_usage_logs_page(p_offset integer DEFAULT 0) RETURNS TABLE(id uuid,user_id uuid,module text,event_kind text,created_at timestamptz) LANGUAGE sql SECURITY INVOKER SET search_path='' AS $$ SELECT * FROM private.admin_usage_logs_page(p_offset); $$;
REVOKE ALL ON FUNCTION public.record_app_usage(text,text),public.admin_module_usage(timestamptz),public.admin_activity_page(integer),public.admin_usage_logs_page(integer),private.record_app_usage(text,text),private.admin_module_usage(timestamptz),private.admin_activity_page(integer),private.admin_usage_logs_page(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.record_app_usage(text,text),public.admin_module_usage(timestamptz),public.admin_activity_page(integer),public.admin_usage_logs_page(integer),private.record_app_usage(text,text),private.admin_module_usage(timestamptz),private.admin_activity_page(integer),private.admin_usage_logs_page(integer) TO authenticated;